						l.read_char()
						return TokenType.NE
					}
				}
				return TokenType.NOT
			}
			'<' => {
				l.read_char()
				if let Some(next) = l.current_char {
					if next == '=' {
						l.read_char()
						return TokenType.LE
					}
				}
				return TokenType.LT
			}
			'>' => {
				l.read_char()
				if let Some(next) = l.current_char {
					if next == '=' {
						l.read_char()
						return TokenType.GE
					}
				}
				return TokenType.GT
			}
			'&' => {
				l.read_char()
				if let Some(next) = l.current_char {
					if next == '&' {
						l.read_char()
						return TokenType.AND
					}
				}
				return TokenType.ERROR
			}
			'|' => {
				l.read_char()
				if let Some(next) = l.current_char {
					if next == '|' {
						l.read_char()
						return TokenType.OR
					}
				}
				return TokenType.ERROR
			}
			_ => {
				return TokenType.ERROR
			}
		}
	}

	return TokenType.ERROR
}

