// ============= 헬퍼 함수 =============

fn (mut cg: CodeGenerator) add_include(header: string) {
	mut found = false
	for inc in cg.includes {
		if inc == header {
			found = true
			break
		}
	}
	if !found {
		cg.includes.push(header)
	}
}

fn (cg: CodeGenerator) get_indent() string {
	let mut result = ""
	for i in 0..cg.indent_level {
		result += "  "
	}
	return result
