		"i64" => "long long"
		"f32" => "float"
		"f64" => "double"
		"bool" => "bool"
		"string" => "char*"
		"void" => "void"
		"byte" => "unsigned char"
		"rune" => "int"
		_ => "void"
	}
}

fn (mut cg: CodeGenerator) type_to_c_with_includes(fv_type: string) string {
	if fv_type == "bool" {
		cg.add_include("<stdbool.h>")
